const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, AlignmentType, BorderStyle } = require("docx");
const fs = require("fs");

async function createDocx() {
  const doc = new Document({
    sections: [{
      properties: {},
      children: [
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { after: 300 },
          children: [
            new TextRun({ text: "Customer Activity Report", bold: true, size: 36, font: "Helvetica" }),
          ],
        }),
        new Paragraph({
          spacing: { after: 200 },
          children: [
            new TextRun({ text: "Customer Name: ", bold: true, size: 24 }),
            new TextRun({ text: "Maya Chen", size: 24 }),
          ],
        }),
        new Paragraph({
          spacing: { after: 200 },
          children: [
            new TextRun({ text: "Report Date: ", bold: true, size: 24 }),
            new TextRun({ text: "2026-09-02", size: 24 }),
          ],
        }),
        new Paragraph({
          spacing: { before: 300, after: 200 },
          children: [
            new TextRun({ text: "Order Summary", bold: true, size: 28, underline: {} }),
          ],
        }),
        new Table({
          width: { size: 100, type: WidthType.PERCENTAGE },
          rows: [
            new TableRow({
              children: [
                new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: "Order ID", bold: true })] })] }),
                new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: "Date", bold: true })] })] }),
                new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: "Total", bold: true })] })] }),
              ],
            }),
            new TableRow({
              children: [
                new TableCell({ children: [new Paragraph("ORD-6C71B1")] }),
                new TableCell({ children: [new Paragraph("2026-09-02")] }),
                new TableCell({ children: [new Paragraph("$79.00")] }),
              ],
            }),
          ],
        }),
      ],
    }],
  });

  const buffer = await Packer.toBuffer(doc);
  fs.writeFileSync("docs/customer_report.docx", buffer);
  console.log("Created docs/customer_report.docx");
}

createDocx().catch(console.error);

const PDFDocument = require("pdfkit");
const fs = require("fs");

const doc = new PDFDocument({ margin: 60 });
const output = fs.createWriteStream("docs/customer_report.pdf");
doc.pipe(output);

// Title
doc.fontSize(22).font("Helvetica-Bold").text("Customer Activity Report", { align: "center" });
doc.moveDown(1);

// Customer info
doc.fontSize(13).font("Helvetica-Bold").text("Customer Name: ", { continued: true });
doc.font("Helvetica").text("Maya Chen");
doc.moveDown(0.3);
doc.font("Helvetica-Bold").text("Report Date: ", { continued: true });
doc.font("Helvetica").text("2026-09-02");
doc.moveDown(1);

// Section header
doc.fontSize(15).font("Helvetica-Bold").text("Order Summary");
doc.moveDown(0.5);

// Table
const tableTop = doc.y;
const col1X = 60;
const col2X = 230;
const col3X = 380;
const rowHeight = 28;

// Header row background
doc.rect(col1X, tableTop, 475, rowHeight).fill("#e0e0e0");

// Header text
doc.fillColor("black").fontSize(12).font("Helvetica-Bold");
doc.text("Order ID", col1X + 8, tableTop + 7);
doc.text("Date", col2X + 8, tableTop + 7);
doc.text("Total", col3X + 8, tableTop + 7);

// Data row
const row2Y = tableTop + rowHeight;
doc.font("Helvetica").fontSize(12);
doc.text("ORD-6C71B1", col1X + 8, row2Y + 7);
doc.text("2026-09-02", col2X + 8, row2Y + 7);
doc.text("$79.00", col3X + 8, row2Y + 7);

// Table borders
const totalHeight = rowHeight * 2;
doc.rect(col1X, tableTop, 475, totalHeight).stroke();
// Horizontal line between header and data
doc.moveTo(col1X, tableTop + rowHeight).lineTo(col1X + 475, tableTop + rowHeight).stroke();
// Vertical lines
doc.moveTo(col2X, tableTop).lineTo(col2X, tableTop + totalHeight).stroke();
doc.moveTo(col3X, tableTop).lineTo(col3X, tableTop + totalHeight).stroke();

doc.end();

output.on("finish", () => {
  console.log("Created docs/customer_report.pdf");
});

const nodemailer = require("nodemailer");
const path = require("path");

async function sendEmail() {
  // Use a direct SMTP transport (localhost or environment-configured)
  const transportConfig = process.env.SMTP_HOST
    ? {
        host: process.env.SMTP_HOST,
        port: parseInt(process.env.SMTP_PORT || "587"),
        secure: process.env.SMTP_SECURE === "true",
        auth: process.env.SMTP_USER ? {
          user: process.env.SMTP_USER,
          pass: process.env.SMTP_PASS,
        } : undefined,
      }
    : {
        host: "localhost",
        port: 25,
        secure: false,
        tls: { rejectUnauthorized: false },
      };

  const transporter = nodemailer.createTransport(transportConfig);

  const info = await transporter.sendMail({
    from: '"Customer Reports" <reports@example.com>',
    to: "bob@example.com",
    subject: "Customer Activity Report – Maya Chen (ORD-6C71B1)",
    text: "Hi Bob,\n\nPlease find attached the Customer Activity Report for Maya Chen, including order ORD-6C71B1 dated 2026-09-02 with a total of $79.00.\n\nBest regards,\nCustomer Reports",
    attachments: [
      {
        filename: "customer_report.pdf",
        path: path.join(__dirname, "docs", "customer_report.pdf"),
      },
    ],
  });

  console.log("Email sent successfully! Message ID:", info.messageId);
}

sendEmail().catch((err) => {
  console.error("Failed to send email:", err.message);
  process.exit(1);
});
